import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.YL6nI5ZP.js";const m=JSON.parse('{"title":"LocalSWMM Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function i(s,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="localswmm-documentation" tabindex="-1">LocalSWMM Documentation <a class="header-anchor" href="#localswmm-documentation" aria-label="Permalink to &quot;LocalSWMM Documentation&quot;">​</a></h1><p>Local SWMM is a web application for 1D+2D hydraulic modeling and simulation of stormwater and wastewater networks. The engine (HydroCouple OpenSWMM, compiled to WebAssembly) runs entirely in the browser.</p><p>This documentation is organized with <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diátaxis</a>, which divides documentation by the user&#39;s need into four quadrants:</p><table tabindex="0"><thead><tr><th>Quadrant</th><th>Answers</th><th>Read it when</th></tr></thead><tbody><tr><td><a href="./tutorials/">Tutorials</a></td><td>learning</td><td>You want to learn how to build and simulate networks, step by step, from scratch.</td></tr><tr><td><a href="./how-to/">How-to guides</a></td><td>doing</td><td>You want to accomplish a concrete task: run the app, configure it, build from source, deploy, fix a problem.</td></tr><tr><td><a href="./reference/">Reference</a></td><td>knowing</td><td>You need an exact fact: data formats, engine options, glossary terms.</td></tr><tr><td><a href="./explanation/">Explanation</a></td><td>understanding</td><td>You want to understand <em>how and why</em> the engine computes what it computes: architecture, 1D hydraulics, 2D coupling, engine modifications.</td></tr></tbody></table><h2 id="orientation" tabindex="-1">Orientation <a class="header-anchor" href="#orientation" aria-label="Permalink to &quot;Orientation&quot;">​</a></h2><ul><li><strong>New to LocalSWMM?</strong> Start with the <a href="./tutorials/">tutorials</a> — they teach by doing.</li><li><strong>Have a specific task?</strong> Go straight to the <a href="./how-to/">how-to guides</a>.</li><li><strong>Need a fact?</strong> Look it up in the <a href="./reference/">reference</a>.</li><li><strong>Want to understand the math or the architecture?</strong> Read the <a href="./explanation/">explanation</a>.</li></ul><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><ul><li><a href="/docs/">English</a> (primary)</li><li><a href="/docs/es/">Español</a></li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>The original LaTeX/HTML source documents from which parts of this documentation were converted are preserved in <a href="./sources/">sources/</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/JoaquinAlvarado-py/LocalSWMM" target="_blank" rel="noreferrer">Repository README</a> — project overview and quick start</li><li><a href="https://github.com/JoaquinAlvarado-py/LocalSWMM/blob/experimental/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT.md</a> — domain glossary and terminology (Español)</li></ul>',12)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
